#!/usr/bin/env node
// Flatten a skill into a single Markdown document for agents that have no skill
// mechanism (plain chat clients, single-file context dumps, offline review).
//
// The bundle inlines the SKILL.md body plus every repository-relative file the
// skill references, so the flattened document is self-contained. Paths are
// resolved inside the skill directory and a path that escapes it is an error,
// never a silent read.
//
// Usage: node scripts/build-bundle.mjs [--skill NAME] [--out DIR] [--quiet]

import fs from 'node:fs';
import path from 'node:path';
import { ROOT, rel, listSkills, extractPathTokens, readText, exists, size } from './lib/skills.mjs';

const argv = process.argv.slice(2);
const argValue = (flag) => { const i = argv.indexOf(flag); return i === -1 ? null : argv[i + 1]; };
const QUIET = argv.includes('--quiet');
const only = argValue('--skill');
const outDir = path.resolve(ROOT, argValue('--out') || 'dist');

const skills = listSkills().filter((s) => !only || s.name === only);
if (skills.length === 0) {
  console.error(only ? `error: no skill named "${only}"` : 'error: no skills found');
  process.exit(2);
}

fs.mkdirSync(outDir, { recursive: true });
const manifest = { generated_from: rel(ROOT), skills: [] };

for (const skill of skills) {
  // Collect the transitive closure of referenced files, breadth-first, so a
  // reference file that points at another file is followed too.
  const queue = skill.refs.filter((r) => r.exists).map((r) => r.token);
  const included = new Map();
  const problems = [];
  const seen = new Set();
  while (queue.length > 0) {
    const token = queue.shift();
    if (seen.has(token)) continue;
    seen.add(token);
    const abs = path.resolve(skill.dir, token);
    if (!abs.startsWith(skill.dir + path.sep) || !exists(abs)) {
      problems.push(token);
      continue;
    }
    if (!/\.(md|markdown|txt|ya?ml|json)$/i.test(abs)) continue; // skip binary assets
    const text = readText(abs);
    included.set(token, text);
    for (const next of extractPathTokens(text, skill.dir)) {
      if (next.exists && !seen.has(next.token) && !included.has(next.token)) queue.push(next.token);
    }
  }

  const parts = [];
  parts.push(`<!--`);
  parts.push(`  Generated bundle: ${skill.name}`);
  parts.push(`  Source: ${rel(skill.skillFile)}`);
  parts.push(`  Build:  node scripts/build-bundle.mjs (do not edit this file by hand)`);
  parts.push('');
  parts.push(`  How to use: paste this whole document as context. Section 1 is the`);
  parts.push(`  operating instruction. Sections 2+ are the reference files the`);
  parts.push(`  instruction routes to; load only the ones the current stage needs,`);
  parts.push(`  in the order the instruction specifies.`);
  parts.push(`-->`);
  parts.push('');
  parts.push(`# ${skill.name} (bundled)`);
  parts.push('');
  parts.push('---');
  parts.push('');
  parts.push('## 1. Operating instruction (SKILL.md)');
  parts.push('');
  parts.push(skill.body.trim());
  parts.push('');
  let index = 2;
  for (const [token, text] of [...included.entries()].sort(([a], [b]) => a.localeCompare(b))) {
    parts.push('---');
    parts.push('');
    parts.push(`## ${index}. Reference: \`${token}\``);
    parts.push('');
    parts.push(text.trim());
    parts.push('');
    index += 1;
  }

  const bundlePath = path.join(outDir, `${skill.name}.bundle.md`);
  const content = parts.join('\n');
  fs.writeFileSync(bundlePath, content);

  const bytes = size(bundlePath);
  manifest.skills.push({
    name: skill.name,
    bundle: rel(bundlePath),
    bytes,
    approx_tokens: Math.round(bytes / 4),
    inlined_files: [...included.keys()].sort(),
    unresolved: problems,
  });

  if (!QUIET) {
    console.log(`${skill.name}`);
    console.log(`  bundle:   ${rel(bundlePath)} (${(bytes / 1024).toFixed(1)} KB, ~${Math.round(bytes / 4 / 1000)}k tokens)`);
    console.log(`  inlined:  ${included.size} file(s)`);
    if (problems.length > 0) console.log(`  WARNING:  ${problems.length} referenced path(s) could not be inlined: ${problems.join(', ')}`);
  }
}

fs.writeFileSync(path.join(outDir, 'manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`);
if (!QUIET) console.log(`\nmanifest: ${rel(path.join(outDir, 'manifest.json'))}`);
if (manifest.skills.some((s) => s.unresolved.length > 0)) {
  console.error('\nerror: some referenced paths could not be inlined; the bundle is incomplete');
  process.exit(1);
}
